begin;
select no_plan();
create temp table collab_fixture as select gen_random_uuid() agency,gen_random_uuid() other_agency,
 gen_random_uuid() manager,gen_random_uuid() recruiter,gen_random_uuid() hirer,gen_random_uuid() reviewer,gen_random_uuid() outsider,
 gen_random_uuid() client,gen_random_uuid() job,gen_random_uuid() hidden_job,gen_random_uuid() candidate,gen_random_uuid() application,
 gen_random_uuid() document,gen_random_uuid() feedback,gen_random_uuid() request,gen_random_uuid() invitation;
grant select on collab_fixture to authenticated,service_role;
insert into auth.users(id,email) select manager,'manager-'||manager||'@example.invalid' from collab_fixture union all select recruiter,'recruiter-'||recruiter||'@example.invalid' from collab_fixture union all select hirer,'hirer-'||hirer||'@example.invalid' from collab_fixture union all select reviewer,'reviewer-'||reviewer||'@example.invalid' from collab_fixture union all select outsider,'outsider-'||outsider||'@example.invalid' from collab_fixture;
insert into public.agencies(id,name,slug,contact_email,country_code,timezone) select agency,'Synthetic collaboration',agency::text,'agency@example.invalid','NG','Africa/Lagos' from collab_fixture union all select other_agency,'Other agency',other_agency::text,'other@example.invalid','NG','Africa/Lagos' from collab_fixture;
insert into public.agency_memberships(agency_id,user_id,role) select agency,manager,'owner' from collab_fixture union all select agency,recruiter,'recruiter' from collab_fixture union all select other_agency,outsider,'owner' from collab_fixture;
insert into public.clients(id,agency_id,name) select client,agency,'Synthetic employer' from collab_fixture;
insert into public.client_memberships(agency_id,client_id,user_id,role) select agency,client,hirer,'hiring_manager' from collab_fixture union all select agency,client,reviewer,'reviewer' from collab_fixture;
insert into public.jobs(id,agency_id,client_id,title,positions_required,created_by) select job,agency,client,'Shared job',2,manager from collab_fixture union all select hidden_job,agency,client,'Private job',1,manager from collab_fixture;
insert into public.job_assignments(agency_id,job_id,user_id,assignment_role) select agency,job,recruiter,'primary' from collab_fixture;
insert into public.candidates(id,agency_id,full_name,email) select candidate,agency,'Synthetic candidate','candidate@example.invalid' from collab_fixture;
insert into public.applications(id,agency_id,job_id,candidate_id) select application,agency,job,candidate from collab_fixture;
insert into public.candidate_documents(id,agency_id,candidate_id,application_id,document_type,file_name,storage_path,content_type,size_bytes) select document,agency,candidate,application,'resume','synthetic.pdf',agency||'/synthetic.pdf','application/pdf',100 from collab_fixture;
select ok(not has_table_privilege('authenticated','public.candidate_submissions','INSERT'),'submissions only via audited operation');
select ok(not has_table_privilege('authenticated','public.submission_feedback','UPDATE'),'feedback is append only');
select ok(not has_function_privilege('anon','public.share_candidate(uuid,uuid,text,boolean,text,uuid,uuid)','EXECUTE'),'anonymous sharing denied');
select ok(not has_function_privilege('authenticated','public.reserve_public_intake(uuid,text)','EXECUTE'),'signed-in callers cannot bypass intake throttle');
select set_config('request.jwt.claim.sub',(select recruiter::text from collab_fixture),true);
set local role authenticated;
select lives_ok($$select public.manage_job_collaborator((select agency from collab_fixture),(select job from collab_fixture),(select hirer from collab_fixture),'grant','grant-1')$$,'assigned recruiter grants explicit job access');
select lives_ok($$select public.manage_job_collaborator((select agency from collab_fixture),(select job from collab_fixture),(select reviewer from collab_fixture),'grant','grant-2')$$,'reviewer access granted');
select lives_ok($$select * from public.job_collaborator_directory((select agency from collab_fixture),(select job from collab_fixture))$$,'assigned recruiter can load employer directory');
select throws_ok($$insert into public.client_invitations(agency_id,client_id,job_id,email,role,token_hash,expires_at,invited_by) select agency,client,job,'escalation@example.invalid','client_administrator','forged-admin-token',now()+interval '1 day',recruiter from collab_fixture$$,'42501',null,'assigned recruiter cannot mint an organization administrator through REST');
select ok(not has_column_privilege('authenticated','public.client_invitations','role','UPDATE'),'invitation role cannot be rewritten after creation');
select throws_ok($$select public.share_candidate((select agency from collab_fixture),(select application from collab_fixture),'Shared candidate summary',false,'share-before-shortlist')$$,'P0001','shortlist_before_sharing','new arrival cannot be shared accidentally');
select throws_ok($$select public.manage_job_collaborator((select agency from collab_fixture),(select hidden_job from collab_fixture),(select hirer from collab_fixture),'grant','no-job-access')$$,'P0001','permission_denied','recruiter cannot grant unrelated job access');
reset role;
update public.applications set status='shortlisted' where id=(select application from collab_fixture);
select set_config('request.jwt.claim.sub',(select recruiter::text from collab_fixture),true);
set local role authenticated;
select lives_ok($$select public.share_candidate((select agency from collab_fixture),(select application from collab_fixture),'Relevant experience, selected by the recruiter.',false,'share-1',(select document from collab_fixture))$$,'explicit sharing succeeds');
select lives_ok($$select public.share_candidate((select agency from collab_fixture),(select application from collab_fixture),'Relevant experience, selected by the recruiter.',false,'share-retry',(select document from collab_fixture))$$,'sharing retry is safe');
select is((select count(*) from public.candidate_submissions),1::bigint,'sharing retry creates one submission');
select set_config('request.jwt.claim.sub',(select hirer::text from collab_fixture),true);
select is((select count(*) from public.portal_memberships()),1::bigint,'portal lists only own active organization');
select is((select count(*) from public.jobs where agency_id=(select agency from collab_fixture)),1::bigint,'employer sees explicit job only');
select is((select count(*) from public.candidate_submissions),1::bigint,'employer sees intentionally shared candidate');
select is((select count(*) from public.applications),0::bigint,'raw application remains internal');
select is((select count(*) from public.candidates),0::bigint,'candidate identity table remains internal');
select is((select count(*) from public.candidate_documents),0::bigint,'private document table remains internal');
select is((select count(*) from public.application_notes),0::bigint,'private notes remain internal');
select lives_ok($$select public.submit_candidate_feedback((select id from public.candidate_submissions),(select feedback from collab_fixture),'{"recommendation":"discuss","comment":"Please discuss relevant experience","strengths":"Clear examples","concerns":"Scope unclear"}','feedback-1')$$,'hiring manager submits structured feedback');
select lives_ok($$select public.submit_candidate_feedback((select id from public.candidate_submissions),(select feedback from collab_fixture),'{"recommendation":"discuss","comment":"Please discuss relevant experience","strengths":"Clear examples","concerns":"Scope unclear"}','feedback-retry')$$,'feedback retry is safe');
select is((select count(*) from public.submission_feedback),1::bigint,'feedback retry creates one record');
select throws_ok($$select public.submit_candidate_feedback((select id from public.candidate_submissions),(select feedback from collab_fixture),'{"recommendation":"pass","comment":"A changed decision"}','feedback-changed')$$,'P0001','idempotency_conflict','feedback request key binds exact contents');
select set_config('request.jwt.claim.sub',(select reviewer::text from collab_fixture),true);
select is((select count(*) from public.candidate_submissions),1::bigint,'reviewer can read shared submission');
select throws_ok($$select public.submit_candidate_feedback((select id from public.candidate_submissions),gen_random_uuid(),'{"recommendation":"proceed","comment":"Reviewer tries feedback"}','reviewer-feedback')$$,'P0001','permission_denied','reviewer cannot write feedback');
select set_config('request.jwt.claim.sub',(select outsider::text from collab_fixture),true);
select is((select count(*) from public.candidate_submissions),0::bigint,'other tenant cannot see submissions');
select is((select count(*) from public.submission_feedback),0::bigint,'other tenant cannot see feedback');
select set_config('request.jwt.claim.sub',(select manager::text from collab_fixture),true);
select is((select count(*) from public.submission_feedback),1::bigint,'agency sees employer feedback');
select lives_ok($$select public.manage_job_collaborator((select agency from collab_fixture),(select job from collab_fixture),(select hirer from collab_fixture),'revoke','revoke-1')$$,'job access can be revoked');
select set_config('request.jwt.claim.sub',(select hirer::text from collab_fixture),true);
select is((select count(*) from public.jobs where agency_id=(select agency from collab_fixture)),0::bigint,'revocation removes job immediately');
select is((select count(*) from public.candidate_submissions),0::bigint,'revocation removes submission immediately');
select is((select count(*) from public.submission_feedback),0::bigint,'revocation removes feedback immediately');
select lives_ok($$select public.save_client_request((select request from collab_fixture),(select client from collab_fixture),'{"title":"New synthetic role","description":"A synthetic description for transactional draft testing","positionsRequired":2,"workArrangement":"remote","requirements":[{"label":"Relevant skill","type":"required"}]}')$$,'hiring manager creates draft atomically');
select lives_ok($$select public.save_client_request((select request from collab_fixture),(select client from collab_fixture),'{"title":"New synthetic role","description":"A synthetic description for transactional draft testing","positionsRequired":2,"workArrangement":"remote","requirements":[{"label":"Relevant skill","type":"required"}]}')$$,'draft creation retry is safe');
select is((select count(*) from public.hiring_requests where id=(select request from collab_fixture)),1::bigint,'one draft after retry');
select is((select count(*) from public.hiring_request_requirements where hiring_request_id=(select request from collab_fixture)),1::bigint,'requirements copied once');
select throws_ok($$select public.save_client_request((select request from collab_fixture),(select client from collab_fixture),'{"title":"Different draft","description":"A different synthetic role description","positionsRequired":1,"workArrangement":"remote"}')$$,'P0001','request_changed','creation key cannot overwrite a draft');
select lives_ok($$select public.submit_hiring_request((select request from collab_fixture),'submit-fixture')$$,'client submits real request');
select is((select count(*) from public.hiring_request_revisions where hiring_request_id=(select request from collab_fixture)),1::bigint,'submission creates immutable revision');
select throws_ok($$select public.save_client_request((select request from collab_fixture),(select client from collab_fixture),'{"title":"Changed submitted","description":"A changed description","positionsRequired":1,"workArrangement":"remote"}',(select updated_at from public.hiring_requests where id=(select request from collab_fixture)))$$,'P0001','request_changed','submitted request cannot be silently edited');
select set_config('request.jwt.claim.sub',(select manager::text from collab_fixture),true);
select lives_ok($$select public.share_candidate((select agency from collab_fixture),(select application from collab_fixture),'',true,'withdraw-1',null,(select id from public.candidate_submissions where application_id=(select application from collab_fixture) and withdrawn_at is null))$$,'agency withdraws shared candidate');
create temp table withdrawn_receipt as select id from public.candidate_submissions where application_id=(select application from collab_fixture) and withdrawn_at is not null;
select lives_ok($$select public.share_candidate((select agency from collab_fixture),(select application from collab_fixture),'A revised recruiter submission for the same candidate.',false,'reshare')$$,'withdrawn application can be intentionally shared again');
select lives_ok($$select public.share_candidate((select agency from collab_fixture),(select application from collab_fixture),'',true,'stale-withdraw',null,(select id from withdrawn_receipt limit 1))$$,'old withdrawal is an idempotent receipt');
select is((select count(*) from public.candidate_submissions where withdrawn_at is null),1::bigint,'stale withdrawal cannot withdraw replacement');
select lives_ok($$select public.share_candidate((select agency from collab_fixture),(select application from collab_fixture),'',true,'withdraw-replacement',null,(select id from public.candidate_submissions where withdrawn_at is null limit 1))$$,'current submission can be withdrawn');
select set_config('request.jwt.claim.sub',(select reviewer::text from collab_fixture),true);
select is((select count(*) from public.candidate_submissions),0::bigint,'withdrawal removes external submission');
reset role;
update public.client_memberships set status='revoked' where user_id=(select reviewer from collab_fixture);
select set_config('request.jwt.claim.sub',(select reviewer::text from collab_fixture),true);
set local role authenticated;
select is((select count(*) from public.portal_memberships()),0::bigint,'revoked client loses portal context');
select is((select count(*) from public.jobs where agency_id=(select agency from collab_fixture)),0::bigint,'membership revocation invalidates retained job grants');
reset role;
insert into public.client_invitations(id,agency_id,client_id,job_id,email,role,token_hash,expires_at,invited_by)
 select invitation,agency,client,job,'hirer-'||hirer||'@example.invalid','hiring_manager','synthetic-invite-'||invitation,now()+interval '1 day',manager from collab_fixture;
select set_config('request.jwt.claim.sub',(select hirer::text from collab_fixture),true);
select set_config('request.jwt.claims',json_build_object('sub',(select hirer from collab_fixture),'email','wrong@example.invalid','role','authenticated')::text,true);
set local role authenticated;
select throws_ok($$select public.accept_client_invitation('synthetic-invite-'||(select invitation from collab_fixture))$$,'P0001','Invitation email does not match signed-in user','invitation cannot be claimed by a different email');
select set_config('request.jwt.claims',json_build_object('sub',(select hirer from collab_fixture),'email',(select 'hirer-'||hirer||'@example.invalid' from collab_fixture),'role','authenticated')::text,true);
select lives_ok($$select public.accept_client_invitation('synthetic-invite-'||(select invitation from collab_fixture))$$,'matching existing user accepts scoped invitation');
select lives_ok($$select public.accept_client_invitation('synthetic-invite-'||(select invitation from collab_fixture))$$,'invitation acceptance retry is safe');
select is((select count(*) from public.jobs where id=(select job from collab_fixture)),1::bigint,'accepted invitation grants intended job');
select is((select count(*) from public.jobs where id=(select hidden_job from collab_fixture)),0::bigint,'accepted invitation grants no other job');
reset role;
delete from public.client_job_access where user_id=(select hirer from collab_fixture);
set local role authenticated;
select lives_ok($$select public.accept_client_invitation('synthetic-invite-'||(select invitation from collab_fixture))$$,'accepted invitation remains an idempotent receipt');
select is((select count(*) from public.jobs where id=(select job from collab_fixture)),0::bigint,'old invitation replay does not restore revoked job access');
reset role;
insert into public.client_invitations(agency_id,client_id,job_id,email,role,token_hash,expires_at,invited_by)
 select agency,client,hidden_job,'hidden-invitation@example.invalid','hiring_manager','hidden-'||invitation,now()+interval '1 day',manager from collab_fixture;
insert into public.communications(agency_id,recipient_email,message_type,related_entity_type,related_entity_id,idempotency_key)
 select agency_id,email,'client_invitation','client_invitation',id,'synthetic-'||id from public.client_invitations where agency_id=(select agency from collab_fixture);
select set_config('request.jwt.claim.sub',(select recruiter::text from collab_fixture),true);
set local role authenticated;
select is((select count(*) from public.communications where message_type='client_invitation'),1::bigint,'assigned recruiter reads only their job invitation delivery');
reset role;
update public.jobs set source='manual' where id=(select hidden_job from collab_fixture);
select set_config('request.jwt.claim.sub',(select manager::text from collab_fixture),true);
set local role authenticated;
select throws_ok($$select public.delete_empty_manual_job((select hidden_job from collab_fixture),'delete-collaboration')$$,'P0001','job_has_collaboration_history','job deletion preserves invitation history');
reset role;
select set_config('request.jwt.claims','{}',true);
select set_config('request.jwt.claim.role','service_role',true);
set local role service_role;
select ok(bool_and(public.reserve_public_intake((select job from collab_fixture),repeat('a',64))),'first ten intake attempts accepted') from generate_series(1,10);
select is(public.reserve_public_intake((select job from collab_fixture),repeat('a',64)),false,'eleventh attempt is throttled');
select is(public.reserve_public_intake((select job from collab_fixture),repeat('b',64)),true,'other fingerprint has independent allowance');
reset role;
select * from finish();
rollback;
